function CommentNode({ comment }: { comment: Comment }) {
  return <div>{comment.replies.map((r) => { return <CommentNode key={r.id} comment={r} />; })}</div>;
}

function countDescendants(c: Comment): number {
  return c.replies.reduce((sum, r) => { return sum + 1 + countDescendants(r); }, 0);
}
